  const criteria = ctx.ticket.acceptance
  if (ctx.judged.length === 0 && criteria.length === 0) return { record: { grade: [] } }
  const out = await ctx.session(`grade-${ctx.pass}`, gradePrompt(ctx.judged, criteria, ctx.base, await diffFor(ctx), ctx.stories), JUDGE_TOOLS, { role: 'grader', onlyTools: true })
